// Writes lib/src/terms.g.dart from the published atomic-plugins ontology.
//
//   dart run tool/gen_terms.dart [ontology-dir]
//
// The default dir is ../../../atomic-plugins/ontology (a sibling checkout of
// atomic-server). Each file there is one JSON-AD term named by its shortname.
import 'dart:convert';
import 'dart:io';

const defaultDir = '../../../atomic-plugins/ontology';

/// The Dart source for the building classes and bldg properties in [dir].
String generate(Directory dir) {
  final out = StringBuffer(
    '// GENERATED by tool/gen_terms.dart from the atomic-plugins ontology.\n'
    '// Do not edit.\n',
  );
  void emit(String name, String sub, String prefix, String strip) {
    final terms = <String, String>{};
    for (final f
        in Directory('${dir.path}/$sub').listSync().whereType<File>()) {
      final id = f.uri.pathSegments.last;
      if (!id.startsWith(prefix)) continue;
      final subject =
          (jsonDecode(f.readAsStringSync()) as Map)['@id'] as String;
      terms[_camel(id, prefix, strip)] = subject;
    }
    out.writeln('\nabstract final class $name {');
    for (final k in terms.keys.toList()..sort()) {
      out.writeln("  static const $k = '${terms[k]}';");
    }
    out.writeln('}');
  }

  emit('BuildingClass', 'classes', 'building-', '-v1');
  emit('Bldg', 'properties', 'bldg-', '');
  // A Question is also an issue: the one non-building class the app uses.
  final issue =
      jsonDecode(File('${dir.path}/classes/issue-v1').readAsStringSync())
          as Map;
  out.writeln(
      "\nabstract final class IssueClass {\n  static const issue = '${issue['@id']}';\n}");
  return out.toString();
}

String _camel(String id, String prefix, String strip) {
  final parts =
      id.substring(prefix.length, id.length - strip.length).split('-');
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

void main(List<String> args) {
  final dir = Directory(args.isEmpty ? defaultDir : args.first);
  if (!dir.existsSync()) {
    stderr.writeln('No ontology directory at ${dir.path}');
    exit(1);
  }
  File('lib/src/terms.g.dart').writeAsStringSync(generate(dir));
}
